package main

import (
	"context"
	"math/rand/v2"
	"slices"
	"time"

	"github.com/corentings/chess/v2"
	"github.com/philyawj/Pandafish/internal/telemetry"
)

type searchResult struct {
	move         string
	depth, score int
	metrics      telemetry.Metrics
}

func rootMoves(position *chess.Position, restriction []string) []chess.Move {
	moves := orderedMoves(position)
	if restriction != nil {
		moves = slices.DeleteFunc(moves, func(move chess.Move) bool {
			return !slices.Contains(restriction, move.String())
		})
	}
	return moves
}

func iterativeSearch(ctx context.Context, position *chess.Position, limits goLimits, budget timeBudget, start time.Time) searchResult {
	return iterativeSearchWithTable(ctx, position, limits, budget, start, newTable())
}

func iterativeSearchWithTable(ctx context.Context, position *chess.Position, limits goLimits, budget timeBudget, start time.Time, table *transpositionTable) searchResult {
	return iterativeSearchWithHistory(ctx, position, limits, budget, start, table, nil)
}

func iterativeSearchWithHistory(ctx context.Context, position *chess.Position, limits goLimits, budget timeBudget, start time.Time, table *transpositionTable, history []uint64) searchResult {
	table.generation++
	worker := searcher{ctx: ctx, table: table, killers: new(killerTable)}
	for _, key := range history {
		worker.pushKey(key)
	}
	if budget.timed {
		worker.deadline = start.Add(budget.hard)
	}
	return worker.iterate(position, rootMoves(position, limits.searchMoves), limits.depth, budget, start)
}

func (worker *searcher) iterate(position *chess.Position, moves []chess.Move, depthLimit int, budget timeBudget, start time.Time) (result searchResult) {
	result = searchResult{move: "0000"}
	reason := "depth"
	defer func() {
		if worker.ctx != nil && worker.ctx.Err() != nil {
			reason = "cancelled"
		} else if !worker.deadline.IsZero() && !worker.clock().Before(worker.deadline) {
			reason = "deadline"
		}
		result.metrics = telemetry.Metrics{
			Depth:     result.depth,
			Nodes:     worker.nodes,
			ElapsedMS: float64(time.Since(start)) / float64(time.Millisecond),
			Timed:     budget.timed,
			SoftMS:    float64(budget.soft) / float64(time.Millisecond),
			HardMS:    float64(budget.hard) / float64(time.Millisecond),
			Reason:    reason,
			Fallback:  result.depth == 0 && result.move != "0000",
			ScoreKind: "unknown",
		}
		if result.depth > 0 {
			result.metrics.ScoreKind, result.metrics.Score = "cp", result.score
			if abs(result.score) >= mateBound {
				result.metrics.ScoreKind, result.metrics.Score = "mate", mateMoves(result.score)
			}
			result.metrics.PV = []string{result.move}
		}
	}()
	if len(moves) == 0 {
		reason = "no_moves"
		return result
	}
	result.move = moves[rand.IntN(len(moves))].String()
	if depthLimit == 0 {
		depthLimit = maxSearchDepth
	}
	for depth := 1; depth <= depthLimit; depth++ {
		reason = "soft_limit"
		if worker.stopped() || (budget.timed && !worker.clock().Before(start.Add(budget.soft))) {
			break
		}
		reason = "interrupted"
		worker.nodes++
		best, score, complete := worker.root(position, moves, depth)
		if !complete {
			break
		}
		result = searchResult{move: best[0], depth: depth, score: score}
		reason = "depth"
		// Search the previous iteration's proven best move first.
		i := slices.IndexFunc(moves, func(move chess.Move) bool { return move.String() == result.move })
		moves[0], moves[i] = moves[i], moves[0]
	}
	return result
}

// root returns one proven best move and its exact score on completion. The
// slice contains exactly one move for a nonempty root; it does not enumerate
// ties. Search each alternative separately with a full window for diagnostics.
func (worker *searcher) root(position *chess.Position, moves []chess.Move, depth int) ([]string, int, bool) {
	worker.pushPosition(position)
	defer worker.popPosition(position)
	var best []string
	bestScore := -searchInfinity
	for _, move := range moves {
		if worker.stopped() {
			return nil, 0, false
		}
		// A fail-high in the child proves the move cannot beat the incumbent.
		// Only a strict improvement replaces it; ties need no exact re-search.
		score, complete := worker.childSearch(position.UpdateSearch(&move), depth-1, -searchInfinity, -bestScore, move.HasTag(chess.Check), 1)
		if !complete {
			return nil, 0, false
		}
		score = -score
		if score > bestScore {
			bestScore, best = score, best[:0]
		}
		if score == bestScore && len(best) == 0 {
			best = append(best, move.String())
		}
	}
	return best, bestScore, !worker.stopped()
}

